INSERT INTO sadesati_phal (phase_key,language,phal_text) VALUES
('phase1','hi','12वें से शनि की पूर्ण 3री दृष्टि 2nd (धन) पर, पूर्ण 10वीं दृष्टि 9th (भाग्य) पर → धन+भाग्य दोनों का नाश। साथ ही 12th स्थिति + 2nd पर दृष्टि से चन्द्रमा/चन्द्र लग्न दोनों ओर से पाप-sandwich → जातक की स्त्री को हानि; लग्न-हानि = स्वास्थ्य, धन, मान की हानि।'),
('phase2','hi','3rd (पुरुषार्थ), 1st/चन्द्र लग्न (मन), 7th (पत्नी), 10th (व्यवसाय) पीड़ित।'),
('phase3','hi','2nd (धन), 5th (पुत्र), 8th (आयु), 11th (आय) पीड़ित — मुख्य प्रभाव चन्द्रमा के पीड़ित होने का। (पुस्तक की सूची as-printed; standard दृष्टि-गणना से 2nd से 4/8/11 बनते हैं — देखें C17।)'),
('general','hi','पाँवों में पीड़ा (12th = चन्द्र कुण्डली का अन्तिम भाव = पाँव), सिर दर्द, धन का नाश, पुत्रों को कष्ट (12th पुत्र-स्थान से अष्टम = पुत्र की आयु-स्वास्थ्य), अपमान।'),
('dhaiyya','hi','शनि जन्म राशि से 4th या 8th में — 2.5 वर्ष। फल साढ़े साती जैसा ही; कारण: यहाँ से भी शनि की दृष्टि लग्न तथा 2nd भाव पर।'),
('pancham','hi','शनि चन्द्र लग्न से 5th में → दृष्टि 2nd व 11th (धन-दौलत के दोनों भाव) तथा 7th (व्यापार स्थान) पर। कन्नड़ कहावत: ''पंचमी शनि फूटे मटके में खाना खिलाता है''। कर्नाटक में साढ़े साती से भी अधिक भय।')
INSERT INTO shani_paya (house_from_moon,metal_hi,shubh,language,effect_hi) VALUES
(1,'सोना (Gold)',0,'hi','सम्बन्धियों से बिगाड़, धन व्यय, झूठा अपराध या लांछन लगना।'),
(2,'चाँदी (Silver)',1,'hi','जायदाद सम्बन्धी कार्यों में लाभ, राज्य से भाग्योदय, सम्बन्धियों से मेल-मिलाप।'),
(3,'ताँबा (Copper)',1,'hi','शुभ समाचार की प्राप्ति, कार्यों में सफलता, राज्य की ओर से मान तथा धन-आय सम्बन्धी फल।'),
(4,'लोहा (Iron)',0,'hi','घरेलू सुख में अशान्ति, सम्बन्धियों से बिगाड़ की सम्भावना, व्यापार में हानि, स्वास्थ्य कष्टदायक।'),
(5,'चाँदी (Silver)',1,'hi','धन का लाभ, सन्तान को सुख।'),
(6,'सोना (Gold)',0,'hi','शत्रुओं से भय, झगड़े में धन का अपव्यय, धन-हानि।'),
(7,'ताँबा (Copper)',1,'hi','(पुस्तक में मकर राशि का उदाहरण नहीं दिया गया — नियम 3,7,10=ताँबा से शुभ फल लें।)'),
(8,'लोहा (Iron)',0,'hi','नियम (4,8,12=लोहा) से अशुभ। (पुस्तक के धनु-उदाहरण में ''ताँबा'' छपा है और शुभ फल दिए हैं — देखें conflict C14।)'),
(9,'चाँदी (Silver)',1,'hi','धर्म में रुचि, सन्तान से सुख, व्यापार में वृद्धि।'),
(10,'ताँबा (Copper)',1,'hi','स्त्री से सुख, बिगड़े हुए कार्यों में सफलता, शत्रुनाश।'),
(11,'सोना (Gold)',0,'hi','सन्तान को कष्ट, स्वास्थ्य में बिगाड़, बने हुए कार्यों में विघ्न।'),
(12,'लोहा (Iron)',0,'hi','शत्रुओं की ओर से कष्ट, स्त्री को कष्ट, धन-हानि तथा यात्राएँ अधिक।')
INSERT INTO lagna_benefics (lagna_sign,language,yogakaraka_hi,shubh_hi,paapi_hi,marak_hi,notes_hi) VALUES
(0,'hi','मंगल (केन्द्र+त्रिकोण; अष्टमेश होकर भी अपनी दशा-भुक्ति में शुभ)','गुरु (नवमेश, बहुत शुभ); सूर्य (पंचमेश)','शनि (एकादशेश-बाधकेश, बहुत पापी); बुध; शुक्र द्वितीयेश → तुला (केन्द्र) का फल → शुभता छोड़ पापी-सा','शुक्र (द्वितीयेश+सप्तमेश, पक्का मारक — दशा में प्रायः मृत्यु); शनि भी प्रायः मारक','गुरु+शनि इकट्ठे हों तो राजयोग नहीं (शनि बहुत पापी)'),
(1,'hi','शनि (एक साथ केन्द्र एवं त्रिकोण का स्वामी)','सूर्य (केन्द्रेश); बुध (पंचमेश)','गुरु (पापी घरों का स्वामी); चन्द्र (तृतीयेश); शुक्र सामान्यतया पापी (लग्नेश पर मूल त्रिकोण राशि 6ठे भाव में)','गुरु (दो अशुभ भावों का स्वामी); मंगल (द्वादशेश+सप्तमेश)','धनेश-लाभेश गुरु+बुध का सम्बन्ध → धनयोग (भावार्थ रत्नाकर)'),
(2,'hi','बुध (लग्नेश)','शुक्र (पंचम भाव का फल, बहुत शुभ)','मंगल, सूर्य (अशुभ स्थानों के स्वामी); गुरु (केन्द्राधिपत्य दोष)','चन्द्र (द्वितीयेश)','गुरु+शनि योग ≠ राजयोग (गुरु केन्द्रेश, शनि त्रिकोणेश+अष्टमेश — पापत्व)'),
(3,'hi','मंगल (केन्द्रेश+त्रिकोणेश, बहुत शुभ); चन्द्र (लग्न केन्द्र भी, त्रिकोण भी)','गुरु कुछ शुभ (षष्ठेश पर शुभ ग्रह व नवमेश)','शुक्र, बुध (पापी भावों के स्वामी)','शनि (सप्तमेश+अष्टमेश); सूर्य — शुभ योग न करे तो मारक','सूर्य ग्रहों से योग करे तो शुभ; शुक्र-दशा में शनि-अन्तर्दशा = अतीव कष्टप्रद (D4)'),
(4,'hi','मंगल (केन्द्र-त्रिकोणेश); सूर्य (लग्नेश)','गुरु (मुख्यतः पंचम भाव का फल)','बुध, शुक्र (तृतीयेश — बहुत पापी), शनि','शनि (सप्तमेश)','शुक्र+गुरु युति ≠ योगकारक; चन्द्र शुभ ग्रहों से सम्बन्धित → शुभ, अन्यथा अशुभ'),
(5,'hi','बुध (लग्नेश)','शुक्र (नवमेश — फल नवम का ही करेगा)','मंगल, चन्द्र (पापी घरों के स्वामी); गुरु (दो केन्द्रों का स्वामी — अशुभ)','गुरु; शुक्र (द्वितीयेश होने से मारक भी)','शनि: मूल त्रिकोण राशि 6ठे → मुख्यतया बुरा फल, पंचमेश से बहुत कम शुभ। सूर्य (द्वादशेश): जैसा प्रभाव वैसा फल'),
(6,'hi','शनि (केन्द्र-त्रिकोण का एकल स्वामी)','बुध (नवमेश)','गुरु, सूर्य (पापी स्थानों के स्वामी); मंगल बहुत कम पापी (नैसर्गिक पापी केन्द्रेश)','चन्द्र (प्रमुख केन्द्र का स्वामी); गुरु भी मारक सिद्ध हो सकता है','चन्द्र+बुध परस्पर सम्बन्ध → दशा-भुक्ति में राजयोग फल। शुक्र सम (लग्नेश जितना शुभ, अष्टमेश उतना पापी)'),
(7,'hi','—','गुरु (पंचमेश); चन्द्र (नवमेश)','बुध, शनि (पापी स्थानों के स्वामी); शुक्र (नैसर्गिक शुभ केन्द्रेश)','शुक्र (सप्तमेश)','सूर्य (केन्द्रेश)+चन्द्र (त्रिकोणेश) युति आदि सम्बन्ध → दशा-भुक्ति में बहुत शुभ। मंगल लग्नेश पर मूल त्रिकोण 6ठे → कोई विशेष अच्छा नहीं'),
(8,'hi','सूर्य+बुध परस्पर सम्बन्ध हो जाए तो योगकारक (बुध केन्द्रेश + सूर्य त्रिकोणेश)','मंगल, सूर्य (त्रिकोण के स्वामी)','शुक्र (पापी घरों का स्वामी)','शनि (द्वितीयेश+तृतीयेश); शुक्र (पापी भावों का स्वामी)','गुरु कम शुभ (लग्नेश + चतुर्थेश — केन्द्राधिपत्य दोष युक्त)'),
(9,'hi','शुक्र (केन्द्र+त्रिकोण का स्वामी, बहुत शुभ)','बुध (मूल त्रिकोण राशि नवम में)','मंगल, गुरु (पापी भावों के स्वामी); चन्द्र (नैसर्गिक शुभ केन्द्रेश)','शनि (द्वितीयेश); मंगल आदि अशुभ ग्रह','शनि लग्नेश-line probable misprint (C21)। सूर्य अष्टमेश पर दोष नहीं लगता → सम फल'),
(10,'hi','शुक्र (केन्द्रेश+त्रिकोणेश, बहुत शुभ)','शनि (लग्नेश)','गुरु, चन्द्र, मंगल (पापी भावों के स्वामी)','गुरु (द्वितीयेश); सूर्य (सप्तमेश); मंगल (पापी भावेश)','बुध सम फल (एक राशि 5वें, दूसरी 8वें — थोड़ा पापी)'),
(11,'hi','गुरु (लग्नेश)','मंगल (नवमेश — द्वितीयेश होकर भी मारक नहीं); चन्द्र (पंचमेश)','शनि, सूर्य, शुक्र (पापी घरों के स्वामी); बुध (केन्द्राधिपत्य दोष से पापी)','बुध (केन्द्रों का स्वामी)','मंगल+गुरु का सम्बन्ध योगकारक (केन्द्र+त्रिकोण स्वामी)')
INSERT INTO house_engine_config (cfg_key,cfg_value,notes) VALUES
('sadesati_paya_mode','ingress','पाया: शनि के राशि-प्रवेश की स्थिति (ingress) — Layer1 से merge नहीं'),
('sadesati_show','1','साढ़े साती/ढैय्या/पंचम शनि खंड दिखाएँ'),
('sadesati_saturn_cycle','29.46','शनि का पूर्ण चक्र (वर्ष) — occurrence गणना हेतु')
