-- =============================================================================
-- Auto Business — Gochar Shani Sade Sati + Paya + Lagna functional (migration 020)
-- Update 04 (Ch.4 Sade Sati) + Update 05 functional table (Lagna_Benefics).
-- Additive Layer-4 overlay on the Gochar engine — does NOT change any Layer-1
-- Saturn text (C16); Paya is a separate indicator, scores not merged (C15).
-- Source: docs/Gochar_Update04_05_06_Combined.md.
-- =============================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS sadesati_phal (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    phase_key VARCHAR(16) NOT NULL, language VARCHAR(8) NOT NULL DEFAULT 'hi',
    phal_text TEXT NOT NULL,
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_ssp (phase_key, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE phal_text=VALUES(phal_text);

CREATE TABLE IF NOT EXISTS shani_paya (
    house_from_moon TINYINT NOT NULL PRIMARY KEY,
    metal_hi VARCHAR(24) NOT NULL, shubh TINYINT NOT NULL DEFAULT 0,
    language VARCHAR(8) NOT NULL DEFAULT 'hi', effect_hi TEXT NOT NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE metal_hi=VALUES(metal_hi),shubh=VALUES(shubh),effect_hi=VALUES(effect_hi);

CREATE TABLE IF NOT EXISTS lagna_benefics (
    lagna_sign TINYINT NOT NULL PRIMARY KEY,  -- 0=Aries..11=Pisces
    language VARCHAR(8) NOT NULL DEFAULT 'hi',
    yogakaraka_hi VARCHAR(255) NULL, shubh_hi VARCHAR(255) NULL,
    paapi_hi VARCHAR(255) NULL, marak_hi VARCHAR(255) NULL, notes_hi VARCHAR(255) NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ON DUPLICATE KEY UPDATE yogakaraka_hi=VALUES(yogakaraka_hi),shubh_hi=VALUES(shubh_hi),paapi_hi=VALUES(paapi_hi),marak_hi=VALUES(marak_hi),notes_hi=VALUES(notes_hi);

ON DUPLICATE KEY UPDATE cfg_value=cfg_value;
-- End of migration 020.
